// Deliberately does ZERO routing/authorization logic - SANOCEA itself decides which merchant an
// email belongs to (packages/email_ingress/service.py::resolve_merchant_from_routing) and rejects
// anything ambiguous. This node only reshapes the raw email + attachment into the JSON body SANOCEA's
// intake endpoint expects - n8n is a transport, never an authority.
const item = $input.first();
const binaryKeys = Object.keys(item.binary || {});
if (binaryKeys.length === 0) {
  throw new Error('No attachment found on this email - nothing to forward to SANOCEA.');
}
const binaryKey = binaryKeys[0];
const binary = item.binary[binaryKey];
return [{
  json: {
    message_id: item.json.messageId || item.json['message-id'] || $execution.id,
    sender: (item.json.from && item.json.from.value && item.json.from.value[0] && item.json.from.value[0].address) || item.json.from || '',
    to_addresses: (item.json.to && item.json.to.value ? item.json.to.value.map(v => v.address) : [item.json.to]).filter(Boolean),
    subject: item.json.subject || '',
    filename: binary.fileName || 'attachment.xlsx',
    content_base64: binary.data,
  }
}];
